import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173
  }
})

/** @type {import('tailwindcss').Config} */
export default {
  content: ['./index.html', './src/**/*.{js,jsx}'],
  darkMode: 'class',
  theme: {
    extend: {
      fontFamily: {
        sans: ['Inter', 'system-ui', 'sans-serif'],
        mono: ['JetBrains Mono', 'Menlo', 'monospace'],
      },
    },
  },
  plugins: [],
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: dark;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', system-ui, sans-serif;
  background: #060910;
  color: #e2e8f0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #334155; border-radius: 999px; }
::-webkit-scrollbar-thumb:hover { background: #475569; }

.glass {
  background: rgba(15, 23, 42, 0.6);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(148, 163, 184, 0.08);
}

.glass-bright {
  background: rgba(30, 41, 59, 0.5);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(148, 163, 184, 0.12);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 12px rgba(59, 130, 246, 0.3); }
  50% { box-shadow: 0 0 24px rgba(59, 130, 246, 0.6); }
}

.animate-fadeIn { animation: fadeIn 0.4s ease-out forwards; }
.animate-slideUp { animation: slideUp 0.5s ease-out forwards; }
.animate-pulseGlow { animation: pulseGlow 2s ease-in-out infinite; }

/* App-level utility styles */

.metric-card {
  transition: all 0.2s ease;
}
.metric-card:hover {
  transform: translateY(-2px);
  border-color: rgba(59, 130, 246, 0.3);
  box-shadow: 0 8px 32px -8px rgba(59, 130, 246, 0.15);
}

.prompt-chip {
  transition: all 0.15s ease;
}
.prompt-chip:hover {
  background: rgba(59, 130, 246, 0.15);
  border-color: rgba(59, 130, 246, 0.4);
  color: #93c5fd;
}

.step-item {
  animation: fadeIn 0.3s ease-out forwards;
  opacity: 0;
}
.step-item:nth-child(1) { animation-delay: 0.05s; }
.step-item:nth-child(2) { animation-delay: 0.1s; }
.step-item:nth-child(3) { animation-delay: 0.15s; }
.step-item:nth-child(4) { animation-delay: 0.2s; }
.step-item:nth-child(5) { animation-delay: 0.25s; }
.step-item:nth-child(6) { animation-delay: 0.3s; }
.step-item:nth-child(7) { animation-delay: 0.35s; }
.step-item:nth-child(8) { animation-delay: 0.4s; }

.sql-block {
  tab-size: 2;
  white-space: pre-wrap;
  word-break: break-all;
}

.tooltip-custom {
  background: #0f172a !important;
  border: 1px solid #334155 !important;
  border-radius: 10px !important;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4) !important;
}

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://127.0.0.1:8000';

export async function apiGet(path) {
  const res = await fetch(`${API_BASE_URL}${path}`);
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`API Error ${res.status}: ${body}`);
  }
  return res.json();
}

export async function apiPost(path, data) {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`API Error ${res.status}: ${body}`);
  }
  return res.json();
}

export default API_BASE_URL;

import React from 'react'
import {
  AreaChart, Area, BarChart, Bar, LineChart, Line,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from 'recharts'
import { TrendingUp, TrendingDown, Minus } from 'lucide-react'

const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null
  return (
    <div className="bg-[#0f172a] border border-slate-700 rounded-xl px-4 py-3 shadow-xl shadow-black/40">
      <p className="text-xs font-medium text-slate-300 mb-2">{label}</p>
      {payload.map((entry, i) => (
        <div key={i} className="flex items-center gap-2 text-xs">
          <div className="w-2.5 h-2.5 rounded-full" style={{ background: entry.color }} />
          <span className="text-slate-400">{entry.name}:</span>
          <span className="font-semibold text-slate-100">{typeof entry.value === 'number' ? entry.value.toLocaleString() : entry.value}</span>
        </div>
      ))}
    </div>
  )
}

function KPIGrid({ data }) {
  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
      {data.map((item, idx) => {
        const statusColors = {
          success: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
          warning: 'text-amber-400 bg-amber-500/10 border-amber-500/20',
          critical: 'text-rose-400 bg-rose-500/10 border-rose-500/20',
          info: 'text-blue-400 bg-blue-500/10 border-blue-500/20',
        }
        const color = statusColors[item.status] || statusColors.info
        const TrendIcon = item.change?.startsWith('-') ? TrendingDown : item.change?.startsWith('+') ? TrendingUp : Minus
        return (
          <div key={idx} className="metric-card glass rounded-xl p-4">
            <p className="text-[11px] text-slate-500 uppercase tracking-wide mb-1">{item.label}</p>
            <p className="text-xl font-bold text-slate-100">{item.value}</p>
            {item.change && (
              <div className={`inline-flex items-center gap-1 mt-2 px-2 py-0.5 rounded-md text-[11px] font-medium border ${color}`}>
                <TrendIcon className="w-3 h-3" />
                {item.change}
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

function ChartWrapper({ title, children }) {
  return (
    <div className="glass rounded-xl p-5">
      <h4 className="text-sm font-semibold text-slate-200 mb-4">{title}</h4>
      {children}
    </div>
  )
}

function renderAreaChart(chart) {
  const { data, config } = chart
  return (
    <ResponsiveContainer width="100%" height={280}>
      <AreaChart data={data} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
        <defs>
          {config.series.map((s, i) => (
            <linearGradient key={i} id={`gradient-${s.key}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={s.color} stopOpacity={0.3} />
              <stop offset="95%" stopColor={s.color} stopOpacity={0} />
            </linearGradient>
          ))}
        </defs>
        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
        <XAxis dataKey={config.xKey} stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
        <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
        <Tooltip content={<CustomTooltip />} />
        <Legend wrapperStyle={{ fontSize: 12 }} />
        {config.series.map((s, i) => (
          <Area
            key={i}
            type="monotone"
            dataKey={s.key}
            name={s.name}
            stroke={s.color}
            strokeWidth={2}
            fill={`url(#gradient-${s.key})`}
          />
        ))}
      </AreaChart>
    </ResponsiveContainer>
  )
}

function renderBarChart(chart) {
  const { data, config } = chart
  return (
    <ResponsiveContainer width="100%" height={280}>
      <BarChart data={data} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
        <XAxis dataKey={config.xKey} stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
        <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
        <Tooltip content={<CustomTooltip />} />
        <Legend wrapperStyle={{ fontSize: 12 }} />
        {config.series.map((s, i) => (
          <Bar key={i} dataKey={s.key} name={s.name} fill={s.color} radius={[4, 4, 0, 0]} />
        ))}
      </BarChart>
    </ResponsiveContainer>
  )
}

function renderLineChart(chart) {
  const { data, config } = chart
  return (
    <ResponsiveContainer width="100%" height={280}>
      <LineChart data={data} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
        <XAxis dataKey={config.xKey} stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
        <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
        <Tooltip content={<CustomTooltip />} />
        <Legend wrapperStyle={{ fontSize: 12 }} />
        {config.series.map((s, i) => (
          <Line key={i} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={2} dot={{ r: 3, fill: s.color }} activeDot={{ r: 5 }} />
        ))}
      </LineChart>
    </ResponsiveContainer>
  )
}

export default function DynamicCharts({ charts }) {
  if (!charts?.length) return null

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
      {charts.map((chart, idx) => {
        if (chart.type === 'kpi') {
          return (
            <div key={idx} className="lg:col-span-2">
              <ChartWrapper title={chart.title}>
                <KPIGrid data={chart.data} />
              </ChartWrapper>
            </div>
          )
        }

        let content = null
        if (chart.type === 'area') content = renderAreaChart(chart)
        else if (chart.type === 'bar') content = renderBarChart(chart)
        else if (chart.type === 'line') content = renderLineChart(chart)
        else content = <p className="text-xs text-slate-500">Unsupported chart type: {chart.type}</p>

        return (
          <ChartWrapper key={idx} title={chart.title}>
            {content}
          </ChartWrapper>
        )
      })}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import {
  HardDrive, Database, Shield, Lock, FileCheck, Activity,
  ArrowRight, CheckCircle2, Loader2, AlertCircle,
  Server, Brain, Code2, BarChart3, Sparkles,
} from 'lucide-react'
import { apiGet } from './config'

const ARCHITECTURE_STEPS = [
  { icon: Sparkles, label: 'User Question', desc: 'Natural language business query', color: 'text-blue-400', bg: 'bg-blue-500/10', border: 'border-blue-500/20' },
  { icon: Brain, label: 'Intent Parser', desc: 'Understand metrics & dimensions', color: 'text-violet-400', bg: 'bg-violet-500/10', border: 'border-violet-500/20' },
  { icon: Shield, label: 'Semantic Mapper', desc: 'Map to governed metrics.yaml', color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' },
  { icon: Code2, label: 'Governed Compiler', desc: 'Compile safe, verified SQL', color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/20' },
  { icon: Database, label: 'SQLite Warehouse', desc: 'Execute against data lakehouse', color: 'text-cyan-400', bg: 'bg-cyan-500/10', border: 'border-cyan-500/20' },
  { icon: BarChart3, label: 'Result Analyzer', desc: 'Analyze patterns & anomalies', color: 'text-rose-400', bg: 'bg-rose-500/10', border: 'border-rose-500/20' },
  { icon: Sparkles, label: 'Executive Insight', desc: 'Generate narrative + charts', color: 'text-indigo-400', bg: 'bg-indigo-500/10', border: 'border-indigo-500/20' },
]

const GOVERNANCE_RULES = [
  { icon: Shield, text: 'All queries compiled from metrics.yaml definitions' },
  { icon: Lock, text: 'No arbitrary SQL generation permitted' },
  { icon: FileCheck, text: 'All metrics verified and approved' },
  { icon: Activity, text: 'Row limits enforced on all queries' },
  { icon: CheckCircle2, text: 'Full audit trail maintained' },
]

export default function WarehouseAudit() {
  const [audit, setAudit] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    apiGet('/api/warehouse/audit')
      .then(d => { setAudit(d); setLoading(false) })
      .catch(err => {
        setError(err.message)
        setAudit({
          primary_table: 'fact_sales',
          total_records: 2016,
          governance_mode: 'SEMANTIC_ONLY',
          max_query_limit: 500,
        })
        setLoading(false)
      })
  }, [])

  if (loading) {
    return (
      <div className="flex items-center justify-center py-32">
        <Loader2 className="w-6 h-6 text-blue-400 animate-spin" />
        <span className="ml-3 text-sm text-slate-400">Loading audit data…</span>
      </div>
    )
  }

  const kpis = [
    { label: 'Primary Table', value: audit?.primary_table || 'fact_sales', icon: Database, color: 'text-blue-400' },
    { label: 'Total Records', value: `${(audit?.total_records || 0).toLocaleString()} Rows`, icon: Server, color: 'text-emerald-400' },
    { label: 'Governance Mode', value: audit?.governance_mode || 'SEMANTIC_ONLY', icon: Shield, color: 'text-violet-400' },
    { label: 'Max Query Limit', value: `${audit?.max_query_limit || 500} Rows`, icon: Lock, color: 'text-amber-400' },
  ]

  return (
    <div className="space-y-8 animate-fadeIn">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
          <HardDrive className="w-4 h-4 text-emerald-400" />
        </div>
        <div>
          <div className="flex items-center gap-2">
            <h2 className="text-xl font-bold text-slate-100">Data Lakehouse Audit</h2>
            <div className="w-2 h-2 rounded-full bg-emerald-400 shadow-sm shadow-emerald-400/50" />
          </div>
          <p className="text-sm text-slate-500">Governed data warehouse status and architecture overview</p>
        </div>
      </div>

      {/* KPI Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {kpis.map((kpi, idx) => {
          const Icon = kpi.icon
          return (
            <div key={idx} className="metric-card glass rounded-xl p-5">
              <div className="flex items-center gap-2 mb-3">
                <Icon className={`w-4 h-4 ${kpi.color}`} />
                <span className="text-[11px] text-slate-500 uppercase tracking-wide">{kpi.label}</span>
              </div>
              <p className="text-lg font-bold text-slate-100 font-mono">{kpi.value}</p>
            </div>
          )
        })}
      </div>

      {/* Architecture Diagram */}
      <div className="glass rounded-xl p-6">
        <h3 className="text-base font-semibold text-slate-200 mb-6">Agentic Pipeline Architecture</h3>
        <div className="flex flex-col lg:flex-row items-stretch gap-2">
          {ARCHITECTURE_STEPS.map((step, idx) => {
            const Icon = step.icon
            return (
              <React.Fragment key={idx}>
                <div className={`flex-1 ${step.bg} ${step.border} border rounded-xl p-4 flex flex-col items-center text-center gap-2 step-item`}>
                  <div className={`w-10 h-10 rounded-full ${step.bg} ${step.border} border flex items-center justify-center`}>
                    <Icon className={`w-5 h-5 ${step.color}`} />
                  </div>
                  <h4 className={`text-xs font-semibold ${step.color}`}>{step.label}</h4>
                  <p className="text-[10px] text-slate-500 leading-relaxed">{step.desc}</p>
                </div>
                {idx < ARCHITECTURE_STEPS.length - 1 && (
                  <div className="flex items-center justify-center lg:py-0 py-1">
                    <ArrowRight className="w-4 h-4 text-slate-600 rotate-90 lg:rotate-0" />
                  </div>
                )}
              </React.Fragment>
            )
          })}
        </div>
      </div>

      {/* Governance Rules */}
      <div className="glass rounded-xl p-6">
        <h3 className="text-base font-semibold text-slate-200 mb-4">Governance Rules</h3>
        <div className="space-y-3">
          {GOVERNANCE_RULES.map((rule, idx) => {
            const Icon = rule.icon
            return (
              <div key={idx} className="flex items-center gap-3 step-item">
                <div className="w-8 h-8 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center shrink-0">
                  <Icon className="w-4 h-4 text-emerald-400" />
                </div>
                <p className="text-sm text-slate-300">{rule.text}</p>
              </div>
            )
          })}
        </div>
      </div>

      {/* Error notice if API failed */}
      {error && (
        <div className="flex items-center gap-2 text-xs text-slate-500 glass rounded-lg px-4 py-3">
          <AlertCircle className="w-3.5 h-3.5 text-amber-400" />
          <span>Showing cached audit data — backend unavailable</span>
        </div>
      )}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import Header from './Header'
import ChatInterface from './ChatInterface'
import MetricStoreExplorer from './MetricStoreExplorer'
import WarehouseAudit from './WarehouseAudit'
import { apiGet } from './config'

export default function App() {
  const [activeTab, setActiveTab] = useState('chat')
  const [health, setHealth] = useState(null)

  useEffect(() => {
    apiGet('/api/health')
      .then(data => setHealth(data))
      .catch(() => setHealth({ status: 'offline', database: 'disconnected', metrics_count: 0 }))
  }, [])

  return (
    <div className="min-h-screen bg-[#060910] text-slate-200 flex flex-col">
      <Header activeTab={activeTab} setActiveTab={setActiveTab} health={health} />
      <main className="flex-1 px-4 sm:px-6 lg:px-8 py-6 max-w-7xl mx-auto w-full">
        {activeTab === 'chat' && <ChatInterface />}
        {activeTab === 'metrics' && <MetricStoreExplorer />}
        {activeTab === 'audit' && <WarehouseAudit />}
      </main>
      <footer className="border-t border-slate-800/60 py-4 px-6 text-center text-xs text-slate-500">
        <span>MetricMind v1.0 — Agentic Semantic BI Engine</span>
        <span className="mx-3 text-slate-700">•</span>
        <span className="text-slate-600 font-mono">Governed Semantic Layer</span>
        <span className="mx-3 text-slate-700">•</span>
        <span className="text-slate-600 font-mono">Zero SQL Hallucination</span>
      </footer>
    </div>
  )
}
